                            role={CONST.ROLE.PRESENTATION}
                            ref={(el) => {
                                if (!inputRef.current) {
                                    updateMultilineInputRange(el);
                                }
                                inputCallbackRef(el);
                            }}
                            shouldSubmitForm
                            isMarkdownEnabled
                        />
                    </View>
                </FormProvider>
            </>
        </ScreenWrapper>
    );
}

